# Frozen local-screen evidence embedded for reproducibility.
# 20 current top-10 public trajectories, all eight first-shop regimes,
# 200 seeds per pairing and both seats = 1,216,000 simulated games.
family_outcome = {'BAKERY': 0.725, 'BRUNCH_SPOT': 0.97375, 'FARMERS_MARKET': 0.824167, 'ICE_CREAM_SHOP': 0.9625, 'PET_CAFE': 0.83875, 'PIZZA_SHOP': 0.632083, 'SMOOTHIE_SHOP': 0.55375, 'YARN_STORE': 0.684318}

summary = {
    "games": 1_216_000,
    "family_macro_outcome": 0.7742897727,
    "minimum_shop_family_outcome": 0.55375,
    "seat_0_outcome": 0.709375,
    "seat_1_outcome": 0.713875,
    "clipped_mean_margin": 5379.9542,
    "opening": "buy 45 wheat, sell 40 wheat",
}

print("Frozen local screen")
for key, value in summary.items():
    print(f"{key:>28}: {value}")


import matplotlib.pyplot as plt

labels = [name.replace("_", " ").title() for name in family_outcome]
values = list(family_outcome.values())
colors = ["#b48a35" if value == min(values) else "#2f6b59" for value in values]

fig, ax = plt.subplots(figsize=(11, 5.2))
bars = ax.barh(labels, values, color=colors)
ax.axvline(0.5, color="#992f2f", linestyle="--", linewidth=1.2, label="even outcome")
ax.set_xlim(0, 1)
ax.set_xlabel("Local route-screen outcome (1 = win, 0.5 = draw)")
ax.set_title("Q45 opening across every first-shop regime", loc="left", weight="bold")
ax.grid(axis="x", alpha=.16)
ax.legend(frameon=False, loc="lower right")
for bar, value in zip(bars, values):
    ax.text(value + .012, bar.get_y() + bar.get_height()/2, f"{value:.3f}", va="center")
plt.tight_layout()
plt.show()


# Materialize the exact, hash-pinned Python agent.
import base64
import hashlib
from pathlib import Path

AGENT_B64 = ''
EXPECTED_AGENT_SHA256 = "7aacd7233e5113e41024db0ff85912ab13cbd164e85ed5438af17df25a85b287"
agent_bytes = base64.b64decode(AGENT_B64)
actual_agent_sha256 = hashlib.sha256(agent_bytes).hexdigest()
assert actual_agent_sha256 == EXPECTED_AGENT_SHA256

output_dir = Path("/kaggle/working") if Path("/kaggle/working").is_dir() else Path.cwd() / "notebook_output"
output_dir.mkdir(parents=True, exist_ok=True)
main_path = output_dir / "main.py"
main_path.write_bytes(agent_bytes)
print(f"main.py: {len(agent_bytes):,} bytes")
print(f"sha256:  {actual_agent_sha256}")


# Structural checks: exact opening, legal response shape, both seats.
namespace = {}
exec(compile(agent_bytes, "main.py", "exec"), namespace)
actions = namespace["_ACTIONS"]
assert len(actions) == 719
assert actions[0]["market"] == [["BUY_PRODUCT", "WHEAT", 45]]
assert actions[1]["market"][0] == ["SELL", "WHEAT", 40]

mock_obs = {"step": 0, "player": 0, "farms": [{"hands": []}, {"hands": []}]}
for seat in (0, 1):
    mock_obs["player"] = seat
    response = namespace["agent"](mock_obs, {})
    assert set(response) == {"farmer", "hands", "market"}
    assert response["market"] == [["BUY_PRODUCT", "WHEAT", 45]]

print("PASS: 719 actions, Q45/Q40 opening, valid response shape, both seats")


# Build a deterministic submission bundle containing exactly root-level main.py.
import gzip
import io
import tarfile

tar_buffer = io.BytesIO()
with tarfile.open(fileobj=tar_buffer, mode="w") as bundle:
    info = tarfile.TarInfo("main.py")
    info.size = len(agent_bytes)
    info.mode = 0o644
    info.mtime = 0
    bundle.addfile(info, io.BytesIO(agent_bytes))

submission_bytes = gzip.compress(tar_buffer.getvalue(), compresslevel=9, mtime=0)
submission_path = output_dir / "submission.tar.gz"
submission_path.write_bytes(submission_bytes)

with tarfile.open(submission_path, "r:gz") as bundle:
    members = bundle.getnames()
    extracted = bundle.extractfile("main.py").read()
assert members == ["main.py"]
assert extracted == agent_bytes

print(f"submission.tar.gz: {len(submission_bytes):,} bytes")
print(f"sha256: {hashlib.sha256(submission_bytes).hexdigest()}")
print("members:", members)


